import '../models/treatment.dart';

/// Projects upcoming doses straight from the treatment rules.
///
/// `DoseEvent` rows only exist for the current day (they are generated by
/// `TherapyProvider.ensureDoseEventsFor` when the app opens), so scheduling
/// system alarms from them would go silent whenever the user skips a day.
/// The planner instead walks the horizon day by day and applies the very same
/// `Treatment.isScheduledOn` rule used for event generation, keeping both
/// paths consistent with ADR 0004 point 3: a daily medicine is a local
/// wall-clock intent ("always at 8 AM local"), not a fixed UTC instant.
///
/// Pure Dart on purpose: everything here is unit-testable without a
/// platform, and the output is a plain value list that
/// `NotificationService` turns into alarm-manager calls.
class DoseNotificationPlanner {
  const DoseNotificationPlanner({
    this.horizonDays = 7,
    this.maxNotifications = 100,
  });

  /// How far ahead to project. Long app absences are covered because every
  /// app open re-syncs; reboots are covered by the plugin's boot receiver
  /// re-scheduling what was persisted.
  final int horizonDays;

  /// Alarm budget. Android allows ~500 concurrent alarms per app; staying
  /// far below it keeps room for other apps and makes `cancelAll` cheap.
  final int maxNotifications;

  /// Returns the upcoming doses of [treatments], soonest first, past doses
  /// excluded (the Today screen owns the past: overdue doses are handled
  /// in-app when the user opens the app).
  List<PlannedDose> plan({
    required List<Treatment> treatments,
    required DateTime now,
  }) {
    final startDay = DateTime(now.year, now.month, now.day);
    final endDay = startDay.add(Duration(days: horizonDays));
    final planned = <PlannedDose>[];

    for (final treatment in treatments) {
      var day = startDay;
      while (!day.isAfter(endDay)) {
        if (treatment.isScheduledOn(day)) {
          for (final doseTime in treatment.doseTimes) {
            final scheduledAt = DateTime(
              day.year,
              day.month,
              day.day,
              doseTime.hour,
              doseTime.minute,
            );
            if (!scheduledAt.isAfter(now)) continue;
            planned.add(
              PlannedDose(
                treatmentId: treatment.id,
                treatmentName: treatment.name,
                dosage: treatment.dosage,
                scheduledAt: scheduledAt,
                notificationId: stableId(treatment.id, scheduledAt),
              ),
            );
          }
        }
        day = day.add(const Duration(days: 1));
      }
    }

    planned.sort((a, b) => a.scheduledAt.compareTo(b.scheduledAt));
    if (planned.length > maxNotifications) {
      return planned.sublist(0, maxNotifications);
    }
    return planned;
  }

  /// Deterministic int32 id for (treatment, instant). Whole minutes since
  /// epoch XOR a per-treatment hash: the same treatment at the same minute
  /// always yields the same id (so re-scheduling overwrites instead of
  /// duplicating), and two instants of the same treatment can never collide
  /// (different minutes imply different XOR results).
  static int stableId(String treatmentId, DateTime scheduledAt) {
    final minutes = scheduledAt.millisecondsSinceEpoch ~/ 60000;
    return (treatmentId.hashCode ^ minutes) & 0x7fffffff;
  }
}

/// One upcoming dose worth a system notification.
class PlannedDose {
  const PlannedDose({
    required this.treatmentId,
    required this.treatmentName,
    required this.dosage,
    required this.scheduledAt,
    required this.notificationId,
  });

  final String treatmentId;
  final String treatmentName;
  final String dosage;

  /// Local wall-clock instant when the dose is due.
  final DateTime scheduledAt;

  final int notificationId;
}
